prompt:
LookupSurcharge returns sql.ErrNoRows when a lane has no surcharge row, and the handler turns that into a 500. A missing row should come back as zero with no error. Change it.

func (s *Store) LookupSurcharge(ctx context.Context, lane string) (Cents, error) {
	var c Cents
	err := s.db.QueryRowContext(ctx, `SELECT amount_cents FROM surcharges WHERE lane = $1`, lane).Scan(&c)
	return c, err
}
